import update from "immutability-helper";
const namespace = "commonrule";

// Action Type
const ActionType = {
  SET_RULES: `${namespace}.setRules`,
  SET_RULE_STRUCTURE: `${namespace}.setRuleStructure`,
  ADD_RULE: `${namespace}.addRule`,
  EDIT_RULE: `${namespace}.editRule`,
  REMOVE_RULE: `${namespace}.removeRule`,
  MOVE_RULE: `${namespace}.moveRule`,
  ADD_ACTION: `${namespace}.addAction`,
  EDIT_ACTION: `${namespace}.editAction`,
  REMOVE_ACTION: `${namespace}.removeAction`,
  ADD_CONDITION: `${namespace}.addCondition`,
  EDIT_CONDITION: `${namespace}.editCondition`,
  EDIT_LEFT_CONDITION: `${namespace}.editLeftCondition`,
  EDIT_RIGHT_CONDITION: `${namespace}.editRightCondition`,
  REMOVE_CONDITION: `${namespace}.removeCondition`,
  REMOVE_OPERATOR: `${namespace}.removeOperator`,
};

update.extend("$autoObject", (value, object) =>
  object ? update(object, value) : update({}, value)
);
update.extend("$autoArray", (value, object) =>
  object ? update(object, value) : update([], value)
);

// Selector
export const commonRulesSelector = {
  getRulesLength(state) {
    return state[namespace].rules.length;
  },
  getRules(state) {
    return state[namespace].rules;
  },
  getRule(state, index) {
    return state[namespace].rules[index];
  },
  getRuleStructures(state) {
    return state[namespace].rulestructures;
  },
};

// Reducers
const initialState = {
  rules: [],
  rulestructures: {},
};

export const commonRulesReducers = {
  [namespace](state = initialState, action) {
    switch (action.type) {
      case ActionType.SET_RULES: {
        return update(state, {
          rules: { $set: action.data.rules },
        });
      }
      case ActionType.SET_RULE_STRUCTURE: {
        return update(state, {
          rulestructures: { $set: action.rulestructures },
        });
      }
      case ActionType.ADD_RULE: {
        return update(state, {
          rules: { $push: [action.rule] },
        });
      }
      case ActionType.EDIT_RULE: {
        const { rules } = state;
        action.rule.conditions = rules[action.index].conditions;
        action.rule.actions = rules[action.index].actions;
        return update(state, {
          rules: { [action.index]: { $set: action.rule } },
        });
      }
      case ActionType.REMOVE_RULE: {
        return update(state, {
          rules: { $splice: [[[action.index], 1]] },
        });
      }
      case ActionType.MOVE_RULE: {
        const { index, targetIndex } = action;
        const { rules } = state;
        if (
          index < 0 ||
          targetIndex < 0 ||
          index >= rules.length ||
          targetIndex >= rules.length
        ) {
          return state;
        }
        const nextRules = rules.slice();
        const moved = nextRules[index];
        nextRules[index] = nextRules[targetIndex];
        nextRules[targetIndex] = moved;
        return update(state, {
          rules: { $set: nextRules },
        });
      }
      case ActionType.ADD_ACTION: {
        return update(state, {
          rules: {
            [action.ruleIndex]: { actions: { $push: [action.action] } },
          },
        });
      }
      case ActionType.EDIT_ACTION: {
        return update(state, {
          rules: {
            [action.ruleIndex]: {
              actions: { [action.actionIndex]: { $set: action.action } },
            },
          },
        });
      }
      case ActionType.REMOVE_ACTION: {
        return update(state, {
          rules: {
            [action.ruleIndex]: {
              actions: { $splice: [[[action.actionIndex], 1]] },
            },
          },
        });
      }
      case ActionType.ADD_CONDITION: {
        return update(state, {
          rules: {
            [action.ruleIndex]: { conditions: { $push: [action.condition] } },
          },
        });
      }
      case ActionType.EDIT_CONDITION: {
        let condIndex = {};
        for (let i = action.conditionIndex.length - 1; i >= 0; i--) {
          const idx = action.conditionIndex[i];
          if (i === action.conditionIndex.length - 1) {
            condIndex = { [idx]: { $set: action.condition } };
          } else {
            condIndex = { [idx]: condIndex };
          }
        }
        return update(state, {
          rules: { [action.ruleIndex]: { conditions: condIndex } },
        });
      }
      case ActionType.EDIT_LEFT_CONDITION: {
        let condLeftIndex = {};
        for (let i = action.conditionIndex.length - 1; i >= 0; i--) {
          const idx = action.conditionIndex[i];
          if (i === action.conditionIndex.length - 1) {
            const left = [action.leftCondition];
            condLeftIndex = { [idx]: { leaf: { $set: left } } };
          } else {
            condLeftIndex = { [idx]: condLeftIndex };
          }
        }
        return update(state, {
          rules: { [action.ruleIndex]: { conditions: condLeftIndex } },
        });
      }
      case ActionType.EDIT_RIGHT_CONDITION: {
        let condRightIndex = {};
        for (let i = action.conditionIndex.length - 1; i >= 0; i--) {
          const idx = action.conditionIndex[i];
          if (i === action.conditionIndex.length - 1) {
            const right = action.rightCondition;
            condRightIndex = { [idx]: { leaf: { 1: { $set: right } } } };
          } else {
            condRightIndex = { [idx]: condRightIndex };
          }
        }
        return update(state, {
          rules: { [action.ruleIndex]: { conditions: condRightIndex } },
        });
      }
      case ActionType.REMOVE_CONDITION: {
        let rmCondIndex = {};
        for (let i = action.conditionIndex.length - 1; i >= 0; i--) {
          let idx = action.conditionIndex[i];
          if (!isNaN(idx)) {
            idx = Number(idx);
          }
          if (i === action.conditionIndex.length - 1) {
            rmCondIndex = { [idx]: { $set: {} } };
          } else {
            rmCondIndex = { [idx]: rmCondIndex };
          }
        }
        if (
          rmCondIndex.length === 1 &&
          action.conditionIndex.length === 1 &&
          action.conditionIndex[0] === 0
        ) {
          rmCondIndex = [];
        }
        return update(state, {
          rules: { [action.ruleIndex]: { conditions: rmCondIndex } },
        });
      }
      case ActionType.REMOVE_OPERATOR: {
        // Removing an operator (AND/OR/NOT) should delete ONLY the operator
        // node, never any of its operands. A tree slot can hold a single node,
        // so we keep one surviving child in the operator's place and lift the
        // other surviving child (if any) up to the rule's top-level
        // `conditions` list as a separate block. This keeps both the "upper"
        // and "lower" leaf intact at any nesting depth.
        //
        //   - Top-level operator OP(A, B): replaced in place by A, and B is
        //     appended as a new top-level condition.
        //   - Nested operator OP(A, B): its slot becomes A, and B is appended
        //     to the top-level conditions list.
        //   - Unary NOT(A): its slot becomes A (nothing to lift).
        const conditionIndex = action.conditionIndex.map((idx) =>
          isNaN(idx) ? idx : Number(idx)
        );

        const conditions = JSON.parse(
          JSON.stringify(state.rules[action.ruleIndex].conditions || [])
        );

        // Walk to the parent container of the operator node.
        let parent = null;
        let parentKey = null;
        let node = conditions;
        for (let i = 0; i < conditionIndex.length; i++) {
          parent = node;
          parentKey = conditionIndex[i];
          node = node == null ? undefined : node[conditionIndex[i]];
        }

        if (node == null || parent == null || parentKey == null) {
          return state;
        }

        // Determine the surviving children.
        const children = [];
        if (node.leaf && node.leaf.length > 0) {
          if (node.leaf[0] && Object.keys(node.leaf[0]).length > 0) {
            children.push(node.leaf[0]);
          }
          if (
            node.leaf.length > 1 &&
            node.leaf[1] &&
            Object.keys(node.leaf[1]).length > 0
          ) {
            children.push(node.leaf[1]);
          }
        }

        // The first surviving child takes the operator's place; any additional
        // child is lifted to the top-level conditions list.
        const inPlace = children.length > 0 ? children[0] : {};
        const lifted = children.slice(1);

        parent[parentKey] = inPlace;

        for (const child of lifted) {
          conditions.push(child);
        }

        return update(state, {
          rules: { [action.ruleIndex]: { conditions: { $set: conditions } } },
        });
      }
      default:
        return state;
    }
  },
};

// Action Creator
const setRules = (data) => ({
  type: ActionType.SET_RULES,
  data,
});

const setRuleStructure = (data) => ({
  type: ActionType.SET_RULE_STRUCTURE,
  rulestructures: data,
});

const addRule = (rule) => ({
  type: ActionType.ADD_RULE,
  rule,
});

const editRule = (index, rule) => ({
  type: ActionType.EDIT_RULE,
  index,
  rule,
});

const removeRule = (index) => ({
  type: ActionType.REMOVE_RULE,
  index,
});

const moveRule = (index, targetIndex) => ({
  type: ActionType.MOVE_RULE,
  index,
  targetIndex,
});

const addAction = (ruleIndex, action) => ({
  type: ActionType.ADD_ACTION,
  ruleIndex,
  action,
});

const editAction = (ruleIndex, actionIndex, action) => ({
  type: ActionType.EDIT_ACTION,
  ruleIndex,
  actionIndex,
  action,
});

const removeAction = (ruleIndex, actionIndex) => ({
  type: ActionType.REMOVE_ACTION,
  ruleIndex,
  actionIndex,
});

const addCondition = (ruleIndex, condition) => ({
  type: ActionType.ADD_CONDITION,
  ruleIndex,
  condition,
});

const editCondition = (ruleIndex, conditionIndex, condition) => ({
  type: ActionType.EDIT_CONDITION,
  ruleIndex,
  conditionIndex,
  condition,
});

const editLeftCondition = (ruleIndex, conditionIndex, leftCondition) => ({
  type: ActionType.EDIT_LEFT_CONDITION,
  ruleIndex,
  conditionIndex,
  leftCondition,
});

const editRightCondition = (ruleIndex, conditionIndex, rightCondition) => ({
  type: ActionType.EDIT_RIGHT_CONDITION,
  ruleIndex,
  conditionIndex,
  rightCondition,
});

const removeCondition = (ruleIndex, conditionIndex) => ({
  type: ActionType.REMOVE_CONDITION,
  ruleIndex,
  conditionIndex,
});

const removeOperator = (ruleIndex, conditionIndex) => ({
  type: ActionType.REMOVE_OPERATOR,
  ruleIndex,
  conditionIndex,
});

// mapDispatchToProps
export const commonRulesMapDisToProps = {
  setRules,
  setRuleStructure,
  addRule,
  editRule,
  removeRule,
  moveRule,
  addAction,
  editAction,
  removeAction,
  addCondition,
  editCondition,
  editLeftCondition,
  editRightCondition,
  removeCondition,
  removeOperator,
};

// Fetch set
export const fetchRuleSet = (service, props, version) => {
  return _fetchRuleSet(service, props, version).then(({ data: rules }) => {
    props.setRules(rules.data);
  });
};

const _fetchRuleSet = (service, props, version) => {
  return service.loadRuleSet({ ruleSetHeader: props.ruleSetHeader, version });
};

const _fetchRulesStructure = (service, props) => {
  return service.getRulesStructure({ ruleSetHeader: props.ruleSetHeader });
};

export const fetchData = (service, props, version) => {
  return Promise.all([
    _fetchRulesStructure(service, props),
    _fetchRuleSet(service, props, version),
  ]).then(([{ data: ruleStructures }, { data: rules }]) => {
    props.setRuleStructure(ruleStructures.data);
    props.setRules(rules.data);
  });
};
